rules.logic:
// Idempotency: only inject once
if (document.getElementById('community-activity-banner')) return;

// --- Gather source data ---
// Discuss button href
const discussEl = document.querySelector('.fandom-community-header__top-container .wiki-tools a[aria-label="Discuss"]');
const discussHref = discussEl ? discussEl.getAttribute('href') : '#';

// Comments count
const commentsCountEl = document.querySelector('#article-comments-button');
const commentsCount = commentsCountEl ? commentsCountEl.textContent.trim() : '5';

// Comments link href
const commentsLinkEl = document.querySelector('a[data-tracking-label="comments-button"]');
const commentsHref = commentsLinkEl ? commentsLinkEl.getAttribute('href') : '#articleComments';

// Comments section HTML (clone)
const commentsSection = document.querySelector('[data-testid="article-comments-anonymous-section"]');

// --- Build banner ---
const banner = document.createElement('div');
banner.id = 'community-activity-banner';
banner.innerHTML = `
  <div id="community-activity-banner__inner">
    <div id="community-activity-banner__left">
      <span id="community-activity-banner__label">💬 Community Activity</span>
    </div>
    <div id="community-activity-banner__actions">
      <a id="community-discuss-btn" href="${discussHref}" aria-label="Discuss on Fandom Forums">
        <svg class="wds-icon wds-icon-small" aria-hidden="true" focusable="false"><use xlink:href="#wds-icons-discussions-small"/></svg>
        Discuss
      </a>
      <a id="community-comments-btn" href="${commentsHref}" aria-label="Jump to comments">
        <svg class="wds-icon wds-icon-small" aria-hidden="true" focusable="false"><use xlink:href="#wds-icons-comment-small"/></svg>
        ${commentsCount} Comment${commentsCount !== '1' ? 's' : ''}
      </a>
    </div>
  </div>
`;

// --- Inject styles ---
const style = document.createElement('style');
style.id = 'community-activity-banner__styles';
style.textContent = `
  #community-activity-banner {
    width: 100%;
    background: linear-gradient(90deg, #0052a3 0%, #006fde 100%);
    border-radius: 10px;
    margin: 16px 0 20px 0;
    box-shadow: 0 4px 18px rgba(0,82,163,0.18);
    padding: 0;
    box-sizing: border-box;
    overflow: hidden;
  }
  #community-activity-banner__inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 24px;
    flex-wrap: wrap;
    gap: 12px;
  }
  #community-activity-banner__label {
    font-size: 1.15em;
    font-weight: 700;
    color: #fff;
    letter-spacing: 0.02em;
  }
  #community-activity-banner__actions {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    align-items: center;
  }
  #community-discuss-btn,
  #community-comments-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 9px 20px;
    border-radius: 6px;
    font-weight: 700;
    font-size: 0.97em;
    text-decoration: none !important;
    transition: background 0.18s, color 0.18s, box-shadow 0.18s;
    cursor: pointer;
    white-space: nowrap;
  }
  #community-discuss-btn {
    background: #fff;
    color: #006fde !important;
    border: 2px solid #fff;
    box-shadow: 0 2px 8px rgba(0,0,0,0.10);
  }
  #community-discuss-btn:hover {
    background: #e6f0ff;
    color: #003f99 !important;
    box-shadow: 0 4px 14px rgba(0,0,0,0.18);
  }
  #community-comments-btn {
    background: transparent;
    color: #fff !important;
    border: 2px solid rgba(255,255,255,0.65);
  }
  #community-comments-btn:hover {
    background: rgba(255,255,255,0.15);
    border-color: #fff;
    box-shadow: 0 2px 8px rgba(0,0,0,0.12);
  }
  #community-discuss-btn .wds-icon,
  #community-comments-btn .wds-icon {
    width: 16px;
    height: 16px;
    fill: currentColor;
  }
`;

if (!document.getElementById('community-activity-banner__styles')) {
  document.head.appendChild(style);
}

// Insert the banner right after the page-header
element.insertAdjacentElement('afterend', banner);

// Idempotency: check if already styled
if (element.getAttribute('data-promoted') === 'true') return;
element.setAttribute('data-promoted', 'true');

// Restyle the whole comments section to stand out
element.style.background = 'linear-gradient(135deg, #f0f6ff 0%, #e8f2ff 100%)';
element.style.border = '2px solid #006fde';
element.style.borderRadius = '12px';
element.style.padding = '24px 28px';
element.style.marginTop = '8px';
element.style.boxShadow = '0 4px 24px rgba(0,111,222,0.12)';

// Style the counter
const counter = element.querySelector('[data-testid="article-comments-anonymous-counter"]');
if (counter) {
  counter.style.background = '#006fde';
  counter.style.color = '#fff';
  counter.style.display = 'inline-block';
  counter.style.borderRadius = '20px';
  counter.style.padding = '4px 16px';
  counter.style.fontWeight = '700';
  counter.style.fontSize = '1em';
  counter.style.marginBottom = '14px';
  const p = counter.querySelector('p');
  if (p) {
    p.style.margin = '0';
    p.style.color = '#fff';
    p.style.fontWeight = '700';
  }
}

// Style the title
const title = element.querySelector('.ArticleAnonymousComments_anonymousCommentsTitle__tRoCi');
if (title) {
  title.style.color = '#003f99';
  title.style.fontSize = '1.3em';
  title.style.fontWeight = '800';
  title.style.marginTop = '8px';
}

// Style the subtitle
const subtitle = element.querySelector('.ArticleAnonymousComments_anonymousCommentsSubtitle__84DBv');
if (subtitle) {
  subtitle.style.color = '#444';
  subtitle.style.fontSize = '1em';
}

// Style the sign-in button
const signIn = element.querySelector('.ArticleAnonymousComments_anonymousCommentsLogin__NBOXS');
if (signIn) {
  signIn.style.background = '#006fde';
  signIn.style.color = '#fff';
  signIn.style.fontWeight = '700';
  signIn.style.padding = '10px 28px';
  signIn.style.borderRadius = '6px';
  signIn.style.fontSize = '1em';
  signIn.style.letterSpacing = '0.04em';
  signIn.style.display = 'inline-block';
  signIn.style.marginTop = '10px';
}

// Style the icon
const icon = element.querySelector('.ArticleAnonymousComments_anonymousCommentsHeaderIcon__Xm7fB');
if (icon) {
  icon.style.color = '#006fde';
  icon.style.fontSize = '1.4em';
}

// Style the footer (register link)
const footer = element.querySelector('.ArticleAnonymousComments_anonymousCommentsFooter__QDtze');
if (footer) {
  footer.style.color = '#555';
  footer.style.marginTop = '10px';
}

if (element.getAttribute('data-wrapper-promoted') === 'true') return;
element.setAttribute('data-wrapper-promoted', 'true');

// Add a prominent section header above the comments
if (!document.getElementById('comments-section-heading')) {
  const heading = document.createElement('div');
  heading.id = 'comments-section-heading';
  heading.innerHTML = '💬 &nbsp;Join the Conversation';
  heading.style.cssText = `
    font-size: 1.4em;
    font-weight: 800;
    color: #006fde;
    margin-bottom: 14px;
    padding-bottom: 10px;
    border-bottom: 3px solid #006fde;
    letter-spacing: 0.01em;
  `;
  element.insertAdjacentElement('beforebegin', heading);
}

// Style the wrapper itself
element.style.background = 'transparent';
element.style.padding = '0';

if (element.getAttribute('data-header-promoted') === 'true') return;
element.setAttribute('data-header-promoted', 'true');

element.style.background = '#006fde';
element.style.color = '#fff';
element.style.borderRadius = '6px';
element.style.padding = '6px 14px';
element.style.fontWeight = '700';
element.style.border = '2px solid #006fde';
element.style.display = 'inline-flex';
element.style.alignItems = 'center';
element.style.gap = '6px';

// Style the badge counter inside
const badge = element.querySelector('#article-comments-button');
if (badge) {
  badge.style.background = '#fff';
  badge.style.color = '#006fde';
  badge.style.borderRadius = '12px';
  badge.style.padding = '1px 8px';
  badge.style.fontWeight = '800';
  badge.style.fontSize = '0.9em';
}

// Style the icon
const icon = element.querySelector('svg');
if (icon) {
  icon.style.fill = '#fff';
}
